effect.shader:
void main() {
vec2 uv = acScreenNorm;
float aspect = acScreenSize.x / max(acScreenSize.y, 1.0);
vec2 st = uv;
st.x *= aspect;
vec2 c = vec2(center.x * aspect, center.y);
vec2 diff = st - c;
float dist = length(diff);
float distortionAmount = fov / 100.0;
float r;
if (reverse) {
r = dist * (1.0 - distortionAmount * (dist * dist));
} else {
r = dist * (1.0 + distortionAmount * (dist * dist));
}
vec2 dir = diff / max(dist, 0.0001);
vec2 newSt = c + dir * r;
vec2 sampleUv = newSt;
sampleUv.x /= aspect;
sampleUv = (sampleUv - center) / max(scale, 0.001) + center;
vec4 finalColor = texture2DCv(inputImg.texture, clamp(sampleUv, 0.0, 1.0));
if (sampleUv.x < 0.0 || sampleUv.x > 1.0 || sampleUv.y < 0.0 || sampleUv.y > 1.0) {
finalColor = vec4(0.0);
}
vec4 original = texture2DCv(inputImg.texture, uv);
gl_FragColor = mix(original, finalColor, alpha);
}
